import{_ as l,a0 as d,w as o,s as r,ao as p,I as n,x as i,a1 as s,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux 新手必知必會的 10 條 Linux 基本命令 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 新手必知必會的 10 條 Linux 基本命令 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 新手必知必會的 10 條 Linux 基本命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 新手必知必會的 10 條 Linux 基本命令 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember","title":"Linux 新手必知必會的 10 條 Linux 基本命令","tag":"201607","desc":""},"relativePath":"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember.md","filePath":"[post].md"}'),h={name:"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember.md"};function u(c,e,g,b,k,m){const a=d("Link");return o(),r("div",null,[e[13]||(e[13]=p(`<h1 id="linux-新手必知必會的-10-條-linux-基本命令" tabindex="-1">Linux 新手必知必會的 10 條 Linux 基本命令 <a class="header-anchor" href="#linux-新手必知必會的-10-條-linux-基本命令" aria-label="Permalink to “Linux 新手必知必會的 10 條 Linux 基本命令”">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/4225072_orig.png" alt=""></p><p>Linux 對我們的生活產生了巨大的衝擊。至少你的安卓手機使用的就是 Linux 核心。儘管如此，在第一次開始使用 Linux 時你還是會感到難以下手。因為在 Linux 中，通常需要使用終端命令來取代 Windows 系統中的點擊啓動圖標操作。但是不必擔心，這裏我們會介紹 10 個 Linux 基本命令來幫助你開啓 Linux 神秘之旅。</p><h3 id="幫助新手走出第一步的-10-個-linux-基本命令" tabindex="-1">幫助新手走出第一步的 10 個 Linux 基本命令 <a class="header-anchor" href="#幫助新手走出第一步的-10-個-linux-基本命令" aria-label="Permalink to “幫助新手走出第一步的 10 個 Linux 基本命令”">​</a></h3><p>當我們談論 Linux 命令時，實質上是在談論 Linux 系統本身。這短短的 10 個 Linux 基本命令不會讓你變成天才或者 Linux 專家，但是能幫助你輕鬆開始 Linux 之旅。使用這些基本命令會幫助新手們完成 Linux 的日常任務，由於它們的使用頻率如此至高，所以我更樂意稱他們為 Linux 命令之王！</p><p>讓我們開始學習這 10 條 Linux 基本命令吧。</p><h4 id="_1-sudo" tabindex="-1">1. sudo <a class="header-anchor" href="#_1-sudo" aria-label="Permalink to “1. sudo”">​</a></h4><p>這條命令的意思是“以超級用户的身份執行”，是 SuperUserDo 的簡寫，它是新手將要用到的最重要的一條 Linux 命令。當一條單行命令需要 root 權限的時候，<code>sudo</code>命令就派上用場了。你可以在每一條需要 root 權限的命令前都加上<code>sudo</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo su</span></span></code></pre></div><h4 id="_2-ls-list" tabindex="-1">2. ls (list) <a class="header-anchor" href="#_2-ls-list" aria-label="Permalink to “2. ls (list)”">​</a></h4><p>跟其他人一樣，你肯定也經常想看看目錄下都有些什麼東西。使用列表命令，終端會把當前工作目錄下所有的文件以及文件夾展示給你。比如説，我當前處在 /home 文件夾中，我想看看 /home 文件夾中都有哪些文件和目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home$ ls</span></span></code></pre></div><p>在 /home 中執行<code>ls</code>命令將會返回類似下面的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>imad lost+found</span></span></code></pre></div><h4 id="_3-cd" tabindex="-1">3. cd <a class="header-anchor" href="#_3-cd" aria-label="Permalink to “3. cd”">​</a></h4><p>變更目錄命令（cd）是終端中總會被用到的主要命令。它是最常用到的 Linux 基本命令之一。此命令使用非常簡單，當你打算從當前目錄跳轉至某個文件夾時，只需要將文件夾鍵入此命令之後即可。如果你想跳轉至上層目錄，只需要在此命令之後鍵入兩個點 (..) 就可以了。 ​ 舉個例子，我現在處在 /home 目錄中，我想移動到 /home 目錄中的 usr 文件夾下，可以通過以下命令來完成操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home $ cd usr</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/home/usr $</span></span></code></pre></div><h4 id="_4-mkdir" tabindex="-1">4. mkdir <a class="header-anchor" href="#_4-mkdir" aria-label="Permalink to “4. mkdir”">​</a></h4><p>只是可以切換目錄還是不夠完美。有時候你會想要新建一個文件夾或子文件夾。此時可以使用 mkdir 命令來完成操作。使用方法很簡單，只需要把新的文件夾名跟在 mkdir 命令之後就好了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~$ mkdir folderName</span></span></code></pre></div><h4 id="_5-cp" tabindex="-1">5. cp <a class="header-anchor" href="#_5-cp" aria-label="Permalink to “5. cp”">​</a></h4><p>拷貝-粘貼（copy-and-paste）是我們組織文件需要用到的重要命令。使用 <code>cp</code> 命令可以幫助你在終端當中完成拷貝-粘貼操作。首先確定你想要拷貝的文件，然後鍵入打算粘貼此文件的目標位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp src des</span></span></code></pre></div><p>注意：如果目標目錄對新建文件需要 root 權限時，你可以使用 <code>sudo</code> 命令來完成文件拷貝操作。</p><h4 id="_6-rm" tabindex="-1">6. rm <a class="header-anchor" href="#_6-rm" aria-label="Permalink to “6. rm”">​</a></h4><p>rm 命令可以幫助你移除文件甚至目錄。如果不希望每刪除一個文件都提示確認一次，可以用<code>-f</code>參數來強制執行。也可以使用 <code>-r</code> 參數來遞歸的移除文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rm myfile.txt</span></span></code></pre></div><h4 id="_7-apt-get" tabindex="-1">7. apt-get <a class="header-anchor" href="#_7-apt-get" aria-label="Permalink to “7. apt-get”">​</a></h4><p>這個命令會依據發行版的不同而有所區別。在基於 Debian 的發行版中，我們擁有 Advanced Packaging Tool（APT）包管理工具來安裝、移除和升級包。apt-get 命令會幫助你安裝需要在 Linux 系統中運行的軟件。它是一個功能強大的命令列，可以用來幫助你對軟件執行安裝、升級和移除操作。</p><p>在其他發行版中，例如 Fedora、Centos，都各自不同的包管理工具。Fedora 之前使用的是 yum，不過現在 dnf 成了它默認的包管理工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo dnf update</span></span></code></pre></div><h4 id="_8-grep" tabindex="-1">8. grep <a class="header-anchor" href="#_8-grep" aria-label="Permalink to “8. grep”">​</a></h4><p>當你需要查找一個文件，但是又忘記了它具體的位置和路徑時，<code>grep</code> 命令會幫助你解決這個難題。你可以提供文件的關鍵字，使用<code>grep</code>命令來查找到它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep user /etc/passwd</span></span></code></pre></div><h4 id="_9-cat" tabindex="-1">9. cat <a class="header-anchor" href="#_9-cat" aria-label="Permalink to “9. cat”">​</a></h4><p>作為一個用户，你應該會經常需要瀏覽腳本內的文本或者代碼。<code>cat</code>命令是 Linux 系統的基本命令之一，它的用途就是將文件的內容展示給你。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat CMakeLists.txt</span></span></code></pre></div><h4 id="_10-poweroff" tabindex="-1">10. poweroff <a class="header-anchor" href="#_10-poweroff" aria-label="Permalink to “10. poweroff”">​</a></h4><p>最後一個命令是 <code>poweroff</code>。有時你需要直接在終端中執行關機操作。此命令可以完成這個任務。由於關機操作需要 root 權限，所以別忘了在此命令之前添加<code>sudo</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo poweroff</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如我在文章開始所言，這 10 條命令並不會讓你立即成為一個 Linux 大拿，但它們會讓你在初期快速上手 Linux。以這些命令為基礎，給自己設置一個目標，每天學習一到三條命令，這就是此文的目的所在。在下方評論區分享有趣並且有用的命令。別忘了跟你的朋友分享此文。</p><hr>`,43)),n("p",null,[e[1]||(e[1]=i("via: ",-1)),s(a,{href:"http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember"},{default:t(()=>[...e[0]||(e[0]=[i("http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=i("作者：",-1)),s(a,{href:"http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember#comments"},{default:t(()=>[...e[2]||(e[2]=[i("Commenti",-1)])]),_:1}),e[6]||(e[6]=i(" 譯者：",-1)),s(a,{href:"https://github.com/mr-ping"},{default:t(()=>[...e[3]||(e[3]=[i("mr-ping",-1)])]),_:1}),e[7]||(e[7]=i(" 校對：",-1)),s(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=i("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原創編譯，",-1)),s(a,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[i("Linux中國",-1)])]),_:1}),e[12]||(e[12]=i(" 榮譽推出",-1))])])}const y=l(h,[["render",u]]);export{L as __pageData,y as default};
